CREATE EXTENSION IF NOT EXISTS postgis;
DROP TABLE IF EXISTS rivers; CREATE TABLE rivers (river_id int, name text, type text, geom geometry);
DROP TABLE IF EXISTS schools_current; CREATE TABLE schools_current (school_id int, name text, status text, enrollment int, geom geometry);
DROP TABLE IF EXISTS wards; CREATE TABLE wards (ward_id int, name text, population int, avg_elevation_m int, geom geometry);
DROP TABLE IF EXISTS roads; CREATE TABLE roads (road_id int, name text, road_class text, geom geometry);
DROP TABLE IF EXISTS schools_2019_archive; CREATE TABLE schools_2019_archive (school_id int, name text, status text, enrollment_2019 int, geom geometry);
DROP TABLE IF EXISTS hospitals; CREATE TABLE hospitals (hospital_id int, name text, beds int, geom geometry);
DROP TABLE IF EXISTS metro_stations; CREATE TABLE metro_stations (station_id int, name text, daily_ridership int, geom geometry);
DROP TABLE IF EXISTS school_addresses; CREATE TABLE school_addresses (school_id int, address text, is_primary boolean);
